class Solution {
public:
    vector<ListNode*> splitListToParts(ListNode* head, int k) {
        int n = 0;
        for (ListNode* cur = head; cur; cur = cur->next) n++;
        int base = n / k;
        int extra = n % k;
        vector<ListNode*> result;
        result.reserve(k);
        ListNode* cur = head;
        for (int i = 0; i < k; i++) {
            result.push_back(cur);
            int size = base + (i < extra ? 1 : 0);
            for (int j = 0; j < size - 1 && cur; j++) cur = cur->next;
            if (cur) {
                ListNode* nxt = cur->next;
                cur->next = nullptr;
                cur = nxt;
            }
        }
        return result;
    }
};
